const tableSort={http:{key:'total_ms',direction:-1},sql:{key:'total_ms',direction:-1}};
const runLabel=r=>`${r.short_id||r.id.slice(-8)} · ${r.passed===true?'PASS':r.passed===false?'FAIL':r.state} · ${num(r.score)} · ${r.started_at?new Date(r.started_at).toLocaleString('ja-JP'):''}`;
const signed=n=>n==null?'—':`${n>0?'+':''}${num(n,2)}`;
const metricNames={total_ms:'合計 ms',avg_ms:'平均 ms',p95_ms:'p95 ms',p99_ms:'p99 ms',max_ms:'最大 ms',min_ms:'最小 ms',p50_ms:'p50 ms',count:'回数',calls:'回数',errors:'エラー数',response_bytes:'転送 bytes',lock_ms:'ロック ms',rows_sent:'返却行数',rows_examined:'走査行数',rows_examined_per_call:'走査行数 / 回'};

function analysisLabel(run){
 if(run.passed!==true)return '分析不要 / '+(run.passed===false?'FAIL':run.state==='aborted'?'中断':'判定なし');
 return ({pending:'分析待ち',complete:'分析済み',skipped:'分析省略',not_required:'分析不要'})[run.analysis_status]||'分析状態未取得';
}
function metricPair(base,candidate,digits=0){return num(base,digits)+' → '+num(candidate,digits);}
function analysisComparisonNote(q){
 const analysis=q.brief?.review?.latest_analysis,base=analysis?.base_run_id;
 if(!analysis)return q.base_mode==='analysis'?'分析の比較元はまだ記録されていません。':'';
 if((base||null)===(q.base?.id||null))return '';
 if(!base)return '保存済み分析には比較元の記録がありません。表示中の比較についての分析とは限りません。';
 return `保存済み分析は ${base.slice(-8)} との比較です。表示中の比較とは異なります。`;
}

function elapsedSince(value){
 const started=typeof value==='number'?value*1000:Date.parse(value);
 if(!Number.isFinite(started))return '';
 const seconds=Math.max(0,Math.floor((Date.now()-started)/1000));
 return seconds<60?`${seconds}秒`:`${Math.floor(seconds/60)}分${seconds%60}秒`;
}
function operationLines(d){
 const a=d.activity||{},q=d.metrics||{},op=a.operation,lines=[];
 if(op){
  const names={'isuscope run':'ベンチ実行中','isuscope survey-run':'初回ベンチ実行中','deploy.sh':'deploy実行中','rollback.sh':'rollback実行中'};
  lines.push((names[op.operation]||'共有操作実行中')+(elapsedSince(op.started_at)?' · '+elapsedSince(op.started_at)+'経過':''));
 }
 const run=q.latest;
 if(run)lines.push(`直近ベンチ ${(run.short_id||run.id.slice(-8))} · ${analysisLabel(run)}`);
 if(!(op?.operation==='isuscope run'||op?.operation==='isuscope survey-run')){
  for(const r of q.running||[])lines.push(`未終了ベンチの記録 ${r.short_id||r.id.slice(-8)} · 開始から${elapsedSince(r.started_at)||'不明'}（実行継続は未確認）`);
 }
 if(a.deploy){
  const labels={preflight:'事前検査',staging:'配布',building:'build',switching:'切替',validating:'検査',complete:'完了',failed:'失敗'};
  const deploy=a.deploy;
  lines.push(`deploy最終記録: ${labels[deploy.phase]||'状態不明'} · ${time(deploy.recorded_at)}${deploy.commit?' · '+deploy.commit.slice(0,8):''}`);
 }
 if(a.last_deploy_commit)lines.push('最後に成功したdeploy: '+a.last_deploy_commit.slice(0,8));
 if(!op&&!run&&!a.deploy&&!q.running?.length)lines.push('実行・計測の記録はまだありません');
 return lines;
}
function renderOperationStatus(d){
 const root=document.querySelector('#operation-status');root.replaceChildren(...operationLines(d).map(line=>el('p',line)));
 root.title='最新の実行記録。閲覧中のrunとは独立しています。deploy記録は現在の実環境との一致確認ではありません。';
}

function updateRunChoices(d){
 boardState=d;
 const q=d.metrics||{},runs=[...(q.score_history||[])].reverse();
 for(const id of ['run-select','base-select']){
  const select=document.getElementById(id),previous=select.value;
  const options=[...(id==='run-select'?[{value:'',label:'最新のベンチを自動表示'}]:[{value:'auto',label:'分析の比較元に追従'},{value:'',label:'比較なし'}]),...runs.map(r=>({value:r.id,label:runLabel(r)}))];
  if(previous&&!options.some(o=>o.value===previous))options.push({value:previous,label:previous});
  const signature=JSON.stringify(options);
  if(select.dataset.options!==signature){select.replaceChildren(...options.map(o=>{const e=el('option',o.label);e.value=o.value;return e}));select.dataset.options=signature;}
  select.value=previous;
 }
 loadDetails();
}
function updateMeasurementHeader(){
 const q=boardState?.metrics||{},id=document.querySelector('#run-select').value||q.latest?.id;
 const runs=[...(q.score_history||[])].reverse(),index=runs.findIndex(r=>r.id===id),run=runs[index];
